impl EdgeShard {
    pub fn scroll(
        &self,
        request: ScrollRequestInternal,
    ) -> OperationResult<(Vec<RecordInternal>, Option<PointIdType>)> {
        let ScrollRequestInternal {
            offset,
            limit,
            filter,
            with_payload,
            with_vector,
            order_by,
        } = request;

        let limit = limit.unwrap_or(ScrollRequestInternal::default_limit());
        let with_payload = with_payload.unwrap_or(ScrollRequestInternal::default_with_payload());

        match order_by.map(OrderBy::from) {
            None => {
                let limit_plus_one = limit.saturating_add(1);
                let mut records = self.scroll_by_id(
                    offset,
                    limit_plus_one,
                    &with_payload,
                    &with_vector,
                    filter.as_ref(),
                    HwMeasurementAcc::disposable_edge(),
                )?;
                let next_offset = if records.len() > limit {
                    let last_record = records.pop().unwrap();
                    Some(last_record.id)
                } else {
                    None
                };
                Ok((records, next_offset))
            }
            // ... rest of implementation
        }
    }
}

// lib/segment/src/segment/read_view/scroll.rs lines 74-100
pub fn filtered_read_by_index(
    &self,
    offset: Option<PointIdType>,
    limit: Option<usize>,
    condition: &Filter,
    is_stopped: &AtomicBool,
    hw_counter: &HardwareCounterCell,
    deferred_behavior: DeferredBehavior,
) -> OperationResult<Vec<PointIdType>> {
    let cardinality_estimation = self
        .payload_index
        .estimate_cardinality(condition, hw_counter)?;

    let ids_iterator = self
        .payload_index
        .iter_filtered_points(
            condition,
            &cardinality_estimation,
            hw_counter,
            is_stopped,
            deferred_behavior,
        )?
        .filter_map(|internal_id| {
            let external_id = self.id_tracker.external_id(internal_id)?;
            match offset {
                Some(offset) if external_id < offset => None,
                _ => Some(external_id),
            }
        })
        .take(limit.unwrap_or(usize::MAX));

    Ok(ids_iterator.collect())
}
